using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.DependencyInjection;using Microsoft.Extensions.Hosting;using Mbb.Archive.BuildingBlocks.Application;using Mbb.Archive.Modules.Retention.Contracts.IntegrationEvents;
namespace Mbb.Archive.Modules.Retention.Infrastructure.Persistence;
internal sealed class RetentionEvaluator:BackgroundService{private readonly IServiceScopeFactory _scopes;private readonly TimeProvider _time;public RetentionEvaluator(IServiceScopeFactory s,TimeProvider t){_scopes=s;_time=t;}protected override async Task ExecuteAsync(CancellationToken ct){while(!ct.IsCancellationRequested){await using var scope=_scopes.CreateAsyncScope();var repo=scope.ServiceProvider.GetRequiredService<Application.Abstractions.IRetentionRepository>();var db=scope.ServiceProvider.GetRequiredService<RetentionDbContext>();var now=_time.GetUtcNow();var cases=await repo.GetDueCasesAsync(now,100,ct);foreach(var c in cases)if(c.Evaluate(now))db.Enqueue(new RetentionCaseEligibleIntegrationEvent(Guid.CreateVersion7(),c.Id,c.ArchiveRecordId,c.Action.ToString(),now));if(cases.Count>0)await db.SaveChangesAsync(ct);await Task.Delay(TimeSpan.FromHours(1),ct);}}}
internal sealed class RetentionOutboxPublisher:BackgroundService{private readonly IServiceScopeFactory _scopes;private readonly IIntegrationEventPublisher _pub;private readonly TimeProvider _time;private readonly string _worker=$"retention:{Environment.MachineName}:{Guid.CreateVersion7():N}";public RetentionOutboxPublisher(IServiceScopeFactory s,IIntegrationEventPublisher p,TimeProvider t){_scopes=s;_pub=p;_time=t;}protected override async Task ExecuteAsync(CancellationToken ct){while(!ct.IsCancellationRequested){try{var batch=await Claim(ct);foreach(var e in batch)await Publish(e,ct);if(batch.Count==0)await Task.Delay(1000,ct);}catch(OperationCanceledException)when(ct.IsCancellationRequested){break;}catch{await Task.Delay(1000,ct);}}}private async Task<IReadOnlyList<E>> Claim(CancellationToken ct){await using var s=_scopes.CreateAsyncScope();var db=s.ServiceProvider.GetRequiredService<RetentionDbContext>();var n=_time.GetUtcNow();await using var tx=await db.Database.BeginTransactionAsync(ct);var rows=await db.Outbox.FromSqlInterpolated($"""SELECT * FROM retention.outbox_messages WHERE processed_at IS NULL AND dead_lettered_at IS NULL AND next_attempt_at <= {n} AND (locked_until IS NULL OR locked_until < {n}) ORDER BY occurred_at LIMIT 50 FOR UPDATE SKIP LOCKED""").ToListAsync(ct);foreach(var r in rows)r.Lease(_worker,n.AddSeconds(120));await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return rows.Select(x=>new E(x.Id,x.EventName,x.Payload,x.OccurredAt,x.AttemptCount)).ToArray();}private async Task Publish(E e,CancellationToken ct){try{await _pub.PublishAsync(e.Id,e.Name,e.Payload,e.At,ct);await using var s=_scopes.CreateAsyncScope();var db=s.ServiceProvider.GetRequiredService<RetentionDbContext>();var r=await db.Outbox.SingleAsync(x=>x.Id==e.Id,ct);r.Published(_worker,_time.GetUtcNow());await db.SaveChangesAsync(ct);}catch(Exception ex){await using var s=_scopes.CreateAsyncScope();var db=s.ServiceProvider.GetRequiredService<RetentionDbContext>();var r=await db.Outbox.SingleAsync(x=>x.Id==e.Id,ct);var n=_time.GetUtcNow();r.Failed(_worker,ex.Message,n,n.AddSeconds(Math.Min(Math.Pow(2,e.Attempt+1),300)),10);await db.SaveChangesAsync(ct);}}private sealed record E(Guid Id,string Name,string Payload,DateTimeOffset At,int Attempt);}
